"""Holdout checks for the deterministic fact layer (not generated by tools/synthetic_corpus)."""

from __future__ import annotations

from pathlib import Path

import pytest
from docx import Document as WordDocument

from core.document_processor import DocumentProcessor
from core.fact_lookup import answer_question, focused_context, parse_question


@pytest.fixture()
def corpus(tmp_path: Path) -> DocumentProcessor:
    doc = WordDocument()
    doc.add_paragraph("Сводка работы склада на 3 марта 2024 г.")
    doc.add_paragraph("Ответственный: Орлова Д.В.")
    for _ in range(12):
        doc.add_paragraph("Проведены плановые работы по уборке территории и проверке оборудования.")
    doc.add_paragraph("Плановый объём отгрузки — 540 т.")
    doc.add_paragraph("Отгружено фактически 512 т продукции.")
    table = doc.add_table(rows=3, cols=3)
    for col, value in enumerate(["Гос. номер", "Водитель", "Груз"]):
        table.cell(0, col).text = value
    for col, value in enumerate(["A777AA 77", "Шевчук Т.Б.", "щебень"]):  # Latin letters
        table.cell(1, col).text = value
    for col, value in enumerate(["к001мм 750", "Орлова Д.В.", "песок"]):
        table.cell(2, col).text = value
    doc.save(str(tmp_path / "Сводка 03.03.2024.docx"))

    (tmp_path / "Сводка 04.03.2024.txt").write_text(
        "Сводка работы склада за 04.03.2024\n"
        "Ответственный: Шевчук Т.Б.\n"
        "Отгружено фактически 498 т продукции.\n"
        "Орлова Д.В. — в отпуске.\n"
        "А777АА77 выезжал на объект «Север» в 09:10.\n",
        encoding="utf-8",
    )

    import openpyxl

    book = openpyxl.Workbook()
    sheet = book.active
    sheet.append(["Дата", "Показатель", "Значение"])
    sheet.append(["05.03.2024", "Отгружено, т", "530"])
    sheet.append(["05.03.2024", "План, т", "540"])
    sheet.append([])
    sheet.append(["Сотрудник", "Смена"])
    sheet.append(["Орлова Д.В.", "дневная"])
    book.save(str(tmp_path / "Показатели 05.03.2024.xlsx"))

    (tmp_path / "Инструкция.txt").write_text(
        "Водитель Орлова Д.В. проходит инструктаж ежегодно.\n", encoding="utf-8"
    )
    processor = DocumentProcessor(docs_folder=str(tmp_path), recursive=True)
    assert processor.load_documents()
    return processor


def test_value_deep_in_document_and_not_the_plan(corpus) -> None:
    answer = answer_question("Сколько отгружено 3 марта?", corpus)  # no year in the question
    assert answer is not None and answer.confidence >= 0.72
    assert "512" in answer.value
    assert "540" not in answer.value
    assert answer.sources == ["Сводка 03.03.2024.docx"]


def test_table_row_with_latin_plate(corpus) -> None:
    answer = answer_question("Кто водитель автомобиля А777АА 77 3 марта 2024?", corpus)
    assert answer is not None and answer.confidence >= 0.72
    assert "Шевчук" in answer.text


def test_days_worked_skips_vacation_and_reports_undated(corpus) -> None:
    answer = answer_question("Сколько дней работала Орлова Д.В. в марте 2024?", corpus)
    assert answer is not None and answer.kind == "count_days"
    assert answer.value == "2"
    assert "04.03.2024" in answer.text  # listed as not counted (vacation)
    assert "Инструкция.txt" in answer.text  # undated mention is reported, not counted


def test_when_question_lists_all_dates(corpus) -> None:
    answer = answer_question("Когда выезжал автомобиль А777АА77?", corpus)
    assert answer is not None and answer.kind == "list_dates"
    assert "03.03.2024" in answer.text and "04.03.2024" in answer.text


def test_period_values_with_total(corpus) -> None:
    answer = answer_question("Сколько всего отгружено в марте 2024?", corpus)
    assert answer is not None and answer.kind == "period_aggregate"
    assert answer.value == "1 540"  # 512 + 498 + 530, plan rows excluded
    assert answer.text.startswith("**")  # the total leads the answer


def test_descriptive_question_is_left_to_rag(corpus) -> None:
    answer = answer_question("Что известно о работе склада 3 марта 2024?", corpus)
    assert answer is None or answer.confidence < 0.6


def test_unknown_person_is_reported_as_not_found(corpus) -> None:
    answer = answer_question("Сколько дней работал Петров И.И. в марте 2024?", corpus)
    assert answer is not None and answer.confidence < 0.8
    assert "не найдено" in answer.text


def test_question_frame_parsing() -> None:
    frame = parse_question("Сколько смен отработал специалист Кузнецова М.А. в июле 2025?")
    assert frame.kind == "count_days"
    assert [(p.surname, p.initials) for p in frame.persons] == [("Кузнецова", "МА")]
    assert frame.start.isoformat() == "2025-07-01" and frame.end.isoformat() == "2025-07-31"
    plate = parse_question("Кто был водителем автомобиля О346ОВ 77 25 июля 2025 года?")
    assert plate.identifiers == ["O346OB77"]
    assert plate.wants_person and plate.single_day


def test_focused_context_keeps_the_fact_from_the_document_tail(corpus) -> None:
    doc_id = next(d.id for d in corpus.documents if d.name.endswith("03.03.2024.docx"))
    context = focused_context("Сколько отгружено 3 марта 2024?", corpus, [doc_id], max_chars=600)
    assert "512" in context
    assert len(context) <= 700
